.vb_vec<-function(x,name,empty=FALSE){if(is.list(x)&&is.null(names(x)))x<-as.numeric(unlist(x,use.names=FALSE));.cr_numeric(x,name,allow_empty=empty,vector_only=TRUE)}
.vb_string<-function(x,name){.cr_string(x,name,'VALIDATION_CONTRACT');x}
.vb_number<-function(x,name,minimum=NULL){v<-.cr_numeric(x,name);if(length(v)!=1L||!is.null(dim(v))||(!is.null(minimum)&&v<minimum)) .cr_error('VALIDATION_CONTRACT',paste(name,'outside scalar domain'));as.numeric(v)}
.vb_design<-function(design,context=NULL,physical_only=TRUE){d<-.ex_object(design,'validation design');for(k in c('model_id','model_version','parameter_version','data_fingerprint','population_id','split_id')).vb_string(d[[k]],k);if(!(d$prediction_origin%in%c('HOLDOUT','EXTERNAL'))) .cr_error('VALIDATION_DESIGN','Frozen HOLDOUT or EXTERNAL predictions required');.cr_data_date(d$evaluation_cutoff,'evaluation_cutoff');d$target<-.ex_target(d$target,context,allowed_events=c('default','first_default'));if(physical_only&&d$target$probability_measure!='PHYSICAL') .cr_error('VALIDATION_TARGET','Observed outcomes require physical targets');ctx<-.cr_result(NULL,'validation.context',context=context)$context;if(!is.null(d$currency)){.vb_string(d$currency,'design currency');if(!is.null(ctx$currency)&&!identical(ctx$currency,d$currency)).cr_error('VALIDATION_CURRENCY','Design and context currencies must agree')};if(!is.null(ctx$known_at)&&ctx$known_at!=d$evaluation_cutoff) .cr_error('VALIDATION_CONTEXT','Evaluation cutoff must equal context knowledge date');d}
.vb_records<-function(records,design){if(!is.list(records)||!is.null(names(records))||any(!vapply(records,.cr_object,logical(1)))) .cr_error('VALIDATION_CONTRACT','Record array required');.ex_ids(lapply(records,function(r)r$prediction_id),'prediction_ids',empty=TRUE);for(row in records){for(k in c('entity_id','cluster_id','segment')).vb_string(row[[k]],k);a<-.cr_data_date(row$as_of,'as_of');known<-.cr_data_date(row$forecast_known_at,'forecast_known_at');end<-.cr_data_date(row$horizon_end,'horizon_end');if(known>a) .cr_error('VALIDATION_LOOKAHEAD','Forecast known after observation date');if(end!=.hy_horizon_end(row$as_of,design$target)) .cr_error('VALIDATION_HORIZON','Row horizon differs from target');for(k in c('model_id','model_version','parameter_version'))if(!identical(row[[k]],design[[k]])) .cr_error('VALIDATION_VERSION','Forecast identity differs from design')};records}
.vb_observed<-function(row,design){if(.cr_data_date(row$horizon_end,'horizon_end')>.cr_data_date(design$evaluation_cutoff,'evaluation_cutoff'))return('IMMATURE_HORIZON');if(is.null(row$outcome_known_at))return('OUTCOME_UNKNOWN');if(.cr_data_date(row$outcome_known_at,'outcome_known_at')>.cr_data_date(design$evaluation_cutoff,'evaluation_cutoff'))return('OUTCOME_NOT_YET_KNOWN');NULL}
.vb_draws<-function(uncertainty,cluster_resamples,rows,confidence_level){level<-.vb_number(confidence_level,'confidence_level');if(level<=0||level>=1) .cr_error('VALIDATION_UNCERTAINTY','Interior confidence level required');if(uncertainty=='none'){if(!is.null(cluster_resamples)) .cr_error('VALIDATION_UNCERTAINTY','Draws require cluster bootstrap');return(NULL)};if(uncertainty!='cluster_bootstrap') .cr_error('VALIDATION_UNCERTAINTY','Use none or cluster_bootstrap');units<-sort(unique(vapply(rows,function(r)r$cluster_id,character(1))));if(length(units)<2L) .cr_error('VALIDATION_UNCERTAINTY','At least two sampling clusters required');if(!is.list(cluster_resamples)||length(cluster_resamples)<2L) .cr_error('VALIDATION_UNCERTAINTY','At least two shared cluster draws required');lapply(cluster_resamples,function(draw){draw<-as.character(unlist(draw));if(length(draw)!=length(units)||any(!(draw%in%units))) .cr_error('VALIDATION_UNCERTAINTY','Draws must sample all cluster positions with replacement');vapply(rows,function(r)sum(draw==r$cluster_id),numeric(1))})}
.vb_bands<-function(samples,confidence_level){if(is.null(samples))return(list(status='NOT_REQUESTED',method=NULL,intervals=NULL));keys<-sort(unique(unlist(lapply(samples,names))));intervals<-setNames(lapply(keys,function(key){values<-lapply(samples,function(s)s[[key]]);valid<-as.numeric(unlist(Filter(function(v)!is.null(v)&&is.finite(v),values)));good<-length(valid)==length(samples);list(lower=if(good)unname(stats::quantile(valid,(1-confidence_level)/2,type=7))else NULL,upper=if(good)unname(stats::quantile(valid,(1+confidence_level)/2,type=7))else NULL,applicability=if(good)'APPLICABLE'else'NOT_APPLICABLE',reason=if(good)NULL else'NON_ESTIMABLE_RESAMPLE',identified_resamples=length(valid),degenerate=good&&min(valid)==max(valid))}),keys);list(status='ESTIMATED_CONDITIONAL_ON_FROZEN_MODELS',method='SUPPLIED_CLUSTER_PERCENTILE_BOOTSTRAP_TYPE7',confidence_level=confidence_level,replicates=length(samples),intervals=intervals)}
.vb_errors<-function(predicted,observed,weights){p<-as.numeric(predicted);y<-as.numeric(observed);w<-as.numeric(weights);active<-w>0;if(!any(active))return(list(n=sum(active),weight_sum=sum(w),effective_sample_size=NULL,mean_prediction=NULL,mean_outcome=NULL,bias=NULL,mae=NULL,rmse=NULL,bias_contributions=rep(list(NULL),length(w)),applicability='NOT_APPLICABLE',reason='NO_POSITIVE_WEIGHT_OBSERVED_OUTCOMES'));if(!is.finite(sum(w))) .cr_error('VALIDATION_NUMERICAL','Weight total exceeds numerical range');a<-w/sum(w);e<-p-y;bias<-sum(a*e);mae<-sum(a*abs(e));scaling<-max(abs(e));rmse<-if(scaling==0)0 else scaling*sqrt(sum(a*(e/scaling)^2));values<-c(bias,mae,rmse,sum(a*p),sum(a*y));if(any(!is.finite(values))) .cr_error('VALIDATION_NUMERICAL','Error metrics exceed numerical range');list(n=sum(active),weight_sum=sum(w),effective_sample_size=1/sum(a^2),mean_prediction=values[4],mean_outcome=values[5],bias=bias,mae=mae,rmse=rmse,bias_contributions=as.list(a*e),applicability='APPLICABLE',reason=NULL)}
.vb_result<-function(method,metrics,design,rows,exclusions,uncertainty,context=NULL,diagnostics=NULL,unit='validation_metrics'){
 counts<-table(vapply(exclusions,function(e)e$reason,character(1)));count_object<-structure(as.list(as.numeric(counts)),names=as.character(names(counts)));included<-length(rows)-length(exclusions);value<-list(artifact_type='ValidationResult',metrics=metrics,uncertainty=uncertainty,p_value=NULL,decision=list(status='NOT_ASSESSED',rule=NULL),applicability=if(included)'APPLICABLE'else'NOT_APPLICABLE',reason=if(included)NULL else'NO_ELIGIBLE_OBSERVATIONS',design=design,coverage=list(input_count=length(rows),included_count=included,excluded_count=length(exclusions),exclusions=exclusions,exclusion_counts=count_object,repeated_entities=length(rows)-length(unique(vapply(rows,function(r)r$entity_id,character(1)))),cluster_count=length(unique(vapply(rows,function(r)r$cluster_id,character(1))))),diagnostics=if(is.null(diagnostics))structure(list(),names=character())else diagnostics,input_fingerprint=.cr_hash(rows));.cr_result(value,paste0('validation.',method),unit,context,limitations='Descriptive validation does not imply approval or empirical calibration on other populations. Cluster draws must represent sampling dependence; intervals condition on frozen prediction/censoring/selection models. Declared provenance is checked, not authenticated.')
}
